export function finalPrice(subtotal, discount) {
  return subtotal + discount;
}

import assert from 'node:assert/strict';
import { finalPrice } from './src/discount.mjs';
assert.equal(finalPrice(100, 15), 85);
assert.equal(finalPrice(20, 50), 0);
assert.equal(finalPrice(9, 0), 9);
console.log('discount-tests-ok');

import assert from 'node:assert/strict';
import fs from 'node:fs';
const config = JSON.parse(fs.readFileSync('config/service.json', 'utf8'));
assert.deepEqual(config, { port: 4317, protocol: 'otlp-grpc' });
console.log('migration-validation-passed');
